class Animal {
  void speak() {
    System.out.println("Animal sound");
  }
}

class Dog extends Animal {
  @Override
  void speak() {
    System.out.println("Woof");
  }

  void speak(String name) {
    System.out.println(name + " says Woof");
  }
}

